import random, itertools, math, time, collections

def cycles_short(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # count violations by enumerating cycles canonical maybe return set
    E=set(tuple(sorted(e)) for e in edges)
    viol=[]
    # triangles
    for a in range(n):
      for b in adj[a]:
        if b>a:
          for c in adj[b]:
            if c>b and a in adj[c]: viol.append((a,b,c))
    # enumerate simple cycles len 4-6 canonical dfs
    seen=set()
    for start in range(n):
      stack=[(start,[start])]
      while stack:
        v,path=stack.pop()
        if len(path)>6: continue
        for w in adj[v]:
          if w==start and len(path)>=4:
            cyc=path[:]
            # canonical if start min and second < last
            if start==min(cyc) and cyc[1]<cyc[-1]:
              seen.add(tuple(cyc)); viol.append(tuple(cyc))
          elif w>start and w not in path and len(path)<6: # ensure start min
            stack.append((w,path+[w]))
    return viol

def find_for_sizes(sizes, max_time=5):
    parts=[]; idx=0
    for s in sizes:
      parts.append(list(range(idx,idx+s))); idx+=s
    all_edges=[]
    for p in range(3):
      for q in range(p+1,3):
        for u in parts[p]:
          for v in parts[q]:
            all_edges.append((u,v) if u<v else (v,u))
    all_edges=list(dict.fromkeys(all_edges))
    if len(all_edges)<26: return None
    # precompute cycles (3-6) possible among all_edges for cost incremental maybe
    eidx={e:i for i,e in enumerate(all_edges)}
    cycles=[]
    # enumerate all vertex cycles length 3-6 compatible with parts no same part adjacent
    n=sum(sizes)
    part=[None]*n
    for pi,P in enumerate(parts):
      for v in P: part[v]=pi
    for k in range(3,7):
      for verts in itertools.combinations(range(n),k):
        first=verts[0]
        for perm in itertools.permutations(verts[1:]):
          if perm[0]>perm[-1]: continue
          cyc=(first,)+perm
          ok=True; inds=[]
          for a,b in zip(cyc,cyc[1:]+cyc[:1]):
            if part[a]==part[b]: ok=False; break
            e=tuple(sorted((a,b))); inds.append(eidx[e])
          if ok: cycles.append(tuple(inds))
    print('sizes',sizes,'all_edges',len(all_edges),'cycles',len(cycles))
    edge_to_cycles=[[] for _ in all_edges]
    for ci,cy in enumerate(cycles):
      for ei in cy: edge_to_cycles[ei].append(ci)
    start=time.time()
    # greedy random build maybe maximum independent in hypergraph where selected edges no cycle hyperedge fully selected
    for restart in range(10000):
      sel=set()
      rem=list(range(len(all_edges)))
      random.shuffle(rem)
      cyc_count=[0]*len(cycles)
      # greedily add edge with no complete cycle
      improved=True
      while rem:
        # pick random safe edge among candidates maybe min future
        candidates=[]
        for ei in rem:
          safe=True
          for ci in edge_to_cycles[ei]:
            if cyc_count[ci]==len(cycles[ci])-1:
              safe=False; break
          if safe: candidates.append(ei)
        if not candidates: break
        ei=random.choice(candidates)
        sel.add(ei); rem.remove(ei)
        for ci in edge_to_cycles[ei]: cyc_count[ci]+=1
        if len(sel)>=26:
          edges=[all_edges[i] for i in sel]
          print('FOUND greedy restart',restart)
          return edges
      # local search if close
      if restart%100==0:
        print('restart',restart,'best this',len(sel),'time',time.time()-start)
      if time.time()-start>max_time: return None
    return None

